/**
 * Persistence for bulk issue imports: the per-workspace import ledger and the single transaction that writes a whole batch.
 */
import { and, eq, inArray, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import {
  getDb,
  issueImports,
  issueLabels,
  issues,
  labels,
} from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { toIssue } from "./_mappers";
import type { Db } from "@/server/db";
import type { ImportIssueRowInput } from "@/schemas/issue-import";
import type { IssueId, LabelId, OrgId, ProjectId, UserId } from "@/types/common";
import type { Issue } from "@/types/issue";

/** Colour a label gets when an import has to create it. */
const DEFAULT_LABEL_COLOR = "#94a3b8";

export type ImportedRow = Omit<ImportIssueRowInput, "assigneeEmail"> & {
  readonly assigneeId: UserId | null;
};

export type ImportBatch = {
  readonly orgId: OrgId;
  readonly projectId: ProjectId;
  readonly importKey: string;
  readonly authorId: UserId;
  readonly rows: readonly ImportedRow[];
  /** Re-evaluated inside the write transaction against the live issue count. */
  readonly exceedsQuota: (used: number) => boolean;
};

export type StoredImport = {
  readonly projectId: ProjectId;
  readonly issues: readonly Issue[];
};

export type ImportOutcome =
  | { readonly kind: "created"; readonly issues: readonly Issue[] }
  | ({ readonly kind: "replayed" } & StoredImport)
  | { readonly kind: "over_quota" };

type Tx = Parameters<Parameters<Db["transaction"]>[0]>[0];

/** The first import recorded for `importKey` in this workspace, if any. */
export async function findImport(
  orgId: OrgId,
  importKey: string,
): Promise<StoredImport | null> {
  return readImport(getDb(), orgId, importKey);
}

function readImport(
  db: Db | Tx,
  orgId: OrgId,
  importKey: string,
): StoredImport | null {
  const record = db
    .select()
    .from(issueImports)
    .where(
      and(
        orgPredicate(issueImports.orgId, orgId),
        eq(issueImports.importKey, importKey),
      ),
    )
    .get();
  if (!record) return null;

  const ids = JSON.parse(record.issueIds) as string[];
  const rows = ids.length === 0
    ? []
    : db
        .select()
        .from(issues)
        .where(and(orgPredicate(issues.orgId, orgId), inArray(issues.id, ids)))
        .all();

  const labelIdsByIssue = new Map<string, LabelId[]>();
  if (ids.length > 0) {
    const links = db
      .select()
      .from(issueLabels)
      .where(
        and(
          orgPredicate(issueLabels.orgId, orgId),
          inArray(issueLabels.issueId, ids),
        ),
      )
      .all();
    for (const link of links) {
      const list = labelIdsByIssue.get(link.issueId) ?? [];
      list.push(link.labelId as LabelId);
      labelIdsByIssue.set(link.issueId, list);
    }
  }

  const byId = new Map(rows.map((row) => [row.id, row]));
  return {
    projectId: record.projectId as ProjectId,
    issues: ids.flatMap((id) => {
      const row = byId.get(id);
      return row ? [toIssue(row, labelIdsByIssue.get(id) ?? [])] : [];
    }),
  };
}

/**
 * Writes a whole batch atomically: re-checks the key and the quota, numbers the
 * rows after the project's highest number ever used, creates the missing
 * labels once each, inserts the issues in file order and records the key.
 * Everything is synchronous inside one transaction, so a concurrent import of
 * the same key can only ever see all of this or none of it.
 */
export async function importBatch(batch: ImportBatch): Promise<ImportOutcome> {
  return getDb().transaction((tx): ImportOutcome => {
    const existing = readImport(tx, batch.orgId, batch.importKey);
    if (existing) return { kind: "replayed", ...existing };

    const used =
      tx
        .select({ value: sql<number>`count(*)` })
        .from(issues)
        .where(
          and(
            orgPredicate(issues.orgId, batch.orgId),
            eq(issues.projectId, batch.projectId),
            sql`${issues.archivedAt} is null`,
          ),
        )
        .get()?.value ?? 0;
    if (batch.exceedsQuota(used)) return { kind: "over_quota" };

    const stamp = toIsoTimestamp(new Date());

    const labelIdByName = new Map(
      tx
        .select({ id: labels.id, name: labels.name })
        .from(labels)
        .where(orgPredicate(labels.orgId, batch.orgId))
        .all()
        .map((label) => [label.name, label.id as LabelId]),
    );

    const labelIdsPerRow = batch.rows.map((row) =>
      [...new Set(row.labels)].map((name) => {
        let id = labelIdByName.get(name);
        if (id === undefined) {
          id = tx
            .insert(labels)
            .values({
              id: newId(),
              orgId: batch.orgId,
              name,
              color: DEFAULT_LABEL_COLOR,
              description: null,
              createdAt: stamp,
              updatedAt: stamp,
            })
            .returning({ id: labels.id })
            .get().id as LabelId;
          labelIdByName.set(name, id);
        }
        return id;
      }),
    );

    const highest =
      tx
        .select({ value: sql<number | null>`max(${issues.number})` })
        .from(issues)
        .where(
          and(
            orgPredicate(issues.orgId, batch.orgId),
            eq(issues.projectId, batch.projectId),
          ),
        )
        .get()?.value ?? 0;

    // Ids sort by creation time; ordering them ascending keeps file order
    // stable for any listing that falls back on the id.
    const ids = batch.rows.map(() => newId()).sort();

    const created = batch.rows.map((row, index) => {
      const inserted = tx
        .insert(issues)
        .values({
          id: ids[index] as string,
          orgId: batch.orgId,
          projectId: batch.projectId,
          number: highest + index + 1,
          title: row.title,
          description: row.description,
          status: row.status,
          priority: row.priority,
          authorId: batch.authorId,
          assigneeId: row.assigneeId,
          parentId: null,
          estimate: null,
          dueAt: row.dueAt,
          startedAt: null,
          completedAt: null,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .returning()
        .get();

      const labelIds = labelIdsPerRow[index] ?? [];
      if (labelIds.length > 0) {
        tx.insert(issueLabels)
          .values(
            labelIds.map((labelId) => ({
              orgId: batch.orgId,
              issueId: inserted.id,
              labelId,
            })),
          )
          .run();
      }
      return toIssue(inserted, labelIds);
    });

    tx.insert(issueImports)
      .values({
        id: newId(),
        orgId: batch.orgId,
        projectId: batch.projectId,
        importKey: batch.importKey,
        issueIds: JSON.stringify(created.map((issue) => issue.id as IssueId)),
        createdAt: stamp,
      })
      .run();

    return { kind: "created", issues: created };
  });
}
