  if (ids.length > 0) {
    const links = db
      .select()
      .from(issueLabels)
      .where(
        and(
          orgPredicate(issueLabels.orgId, orgId),
          inArray(issueLabels.issueId, ids),
        ),
      )
      .all();
    for (const link of links) {
      const list = labelIdsByIssue.get(link.issueId) ?? [];
      list.push(link.labelId as LabelId);
      labelIdsByIssue.set(link.issueId, list);
    }
  }

  const byId = new Map(rows.map((row) => [row.id, row]));
  return {
    projectId: record.projectId as ProjectId,
    issues: ids.flatMap((id) => {
      const row = byId.get(id);
      return row ? [toIssue(row, labelIdsByIssue.get(id) ?? [])] : [];
    }),
  };
}

/**
 * Writes a whole batch atomically: re-checks the key and the quota, numbers the
 * rows after the project's highest number ever used, creates the missing
 * labels once each, inserts the issues in file order and records the key.
 * Everything is synchronous inside one transaction, so a concurrent import of
 * the same key can only ever see all of this or none of it.
 */
export async function importBatch(batch: ImportBatch): Promise<ImportOutcome> {
  return getDb().transaction((tx): ImportOutcome => {
    const existing = readImport(tx, batch.orgId, batch.importKey);
    if (existing) return { kind: "replayed", ...existing };

    const used =
      tx
        .select({ value: sql<number>`count(*)` })
        .from(issues)
        .where(
          and(
            orgPredicate(issues.orgId, batch.orgId),
            eq(issues.projectId, batch.projectId),
            sql`${issues.archivedAt} is null`,
          ),
        )
        .get()?.value ?? 0;
    if (batch.exceedsQuota(used)) return { kind: "over_quota" };

    const stamp = toIsoTimestamp(new Date());

    const labelIdByName = new Map(
      tx
        .select({ id: labels.id, name: labels.name })
        .from(labels)
        .where(orgPredicate(labels.orgId, batch.orgId))
        .all()
        .map((label) => [label.name, label.id as LabelId]),
    );

    const labelIdsPerRow = batch.rows.map((row) =>
      [...new Set(row.labels)].map((name) => {
        let id = labelIdByName.get(name);
        if (id === undefined) {
          id = tx
            .insert(labels)
            .values({
              id: newId(),
              orgId: batch.orgId,
              name,
              color: DEFAULT_LABEL_COLOR,
              description: null,
              createdAt: stamp,
              updatedAt: stamp,
            })
            .returning({ id: labels.id })
            .get().id as LabelId;
          labelIdByName.set(name, id);
        }
        return id;
      }),
    );

    const highest =
      tx
        .select({ value: sql<number | null>`max(${issues.number})` })
        .from(issues)
        .where(
          and(
            orgPredicate(issues.orgId, batch.orgId),
            eq(issues.projectId, batch.projectId),
          ),
        )
        .get()?.value ?? 0;

    // Ids sort by creation time; ordering them ascending keeps file order
    // stable for any listing that falls back on the id.
    const ids = batch.rows.map(() => newId()).sort();

    const created = batch.rows.map((row, index) => {
      const inserted = tx
        .insert(issues)
        .values({
          id: ids[index] as string,
          orgId: batch.orgId,
          projectId: batch.projectId,
          number: highest + index + 1,
          title: row.title,
          description: row.description,
          status: row.status,
          priority: row.priority,
          authorId: batch.authorId,
          assigneeId: row.assigneeId,
          parentId: null,
          estimate: null,
          dueAt: row.dueAt,
          startedAt: null,
          completedAt: null,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .returning()
        .get();

      const labelIds = labelIdsPerRow[index] ?? [];
      if (labelIds.length > 0) {
        tx.insert(issueLabels)
          .values(
            labelIds.map((labelId) => ({
              orgId: batch.orgId,
              issueId: inserted.id,
              labelId,
            })),
          )
          .run();
      }
      return toIssue(inserted, labelIds);
    });

    tx.insert(issueImports)
      .values({
        id: newId(),
        orgId: batch.orgId,
        projectId: batch.projectId,
        importKey: batch.importKey,
        issueIds: JSON.stringify(created.map((issue) => issue.id as IssueId)),
        createdAt: stamp,
      })
      .run();

    return { kind: "created", issues: created };
  });
}
