const ISSUE_CREATE_BUCKET = "issue:create";

/**
 * Bulk import: the same gates as `createIssue`, applied to the whole batch
 * before anything is written, then one atomic write and a single
 * `issues.imported` event in place of per-issue `issue.created` announcements.
 * A key the workspace has already imported replays the first result untouched.
 */
export async function importIssues(
  actor: Actor,
  input: ImportIssuesInput,
): Promise<IssueImportResult> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  const replay = await issueImportRepo.findImport(input.orgId, input.importKey);
  if (replay) return replayed(input.importKey, replay);

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  const requested = input.rows.length;
  const refuseOverQuota = () =>
    new Error(`Plan ${org.plan} allows no more issues in project ${project.key}`);

  const used = await issueRepo.countIssues(input.orgId, input.projectId);
  if (wouldExceedLimit(org.plan, "issuesPerProject", used, requested)) {
    throw refuseOverQuota();
  }

  const verdict = await consumeRateLimit(
    input.orgId,
    ISSUE_CREATE_BUCKET,
    requested,
  );
  if (!verdict.allowed) {
    throw new Error(
      `Issue rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  const memberIdByEmail = await memberRepo.listActiveMemberEmails(input.orgId);

  const outcome = await issueImportRepo.importBatch({
    orgId: input.orgId,
    projectId: input.projectId,
    importKey: input.importKey,
    authorId: actor.userId,
    rows: input.rows.map(({ assigneeEmail, ...row }) => ({
      ...row,
      assigneeId:
        assigneeEmail === null
          ? null
          : (memberIdByEmail.get(assigneeEmail.toLowerCase()) ?? null),
    })),
    exceedsQuota: (current) =>
      wouldExceedLimit(org.plan, "issuesPerProject", current, requested),
  });

  if (outcome.kind === "over_quota") throw refuseOverQuota();
  if (outcome.kind === "replayed") return replayed(input.importKey, outcome);

  await emit("issues.imported", {
    ...actorEnvelope(actor),
    projectId: input.projectId,
    importKey: input.importKey,
    issueIds: outcome.issues.map((issue) => issue.id),
  });

  return {
    importKey: input.importKey,
    projectId: input.projectId,
    issues: outcome.issues,
    replayed: false,
  };
}

function replayed(
  importKey: string,
  stored: { projectId: ProjectId; issues: readonly Issue[] },
): IssueImportResult {
  return {
    importKey,
    projectId: stored.projectId,
    issues: stored.issues,
    replayed: true,
  };
}

