/**
 * Bulk issue import: gates, all-or-nothing writes, replays and announcements.
 */
import { afterAll, afterEach, beforeAll, beforeEach, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { resetEventBus, subscribe } from "@/lib/event-bus";
import { resetRateLimits } from "@/lib/rate-limit";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import { importIssuesSchema } from "@/schemas/issue-import";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as activityRepo from "@/server/repositories/activity-repository";
import { NotFoundError } from "@/server/services/_support";
import {
  registerEventHandlers,
  unregisterEventHandlers,
} from "@/server/services/event-registry";
import * as issueService from "@/server/services/issue-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { ImportIssuesInput } from "@/schemas/issue-import";
import type { OrgId, ProjectId } from "@/types/common";

let cleanup: () => void;
let tenant: Tenant;
let counter = 0;

function batch(
  t: Tenant,
  rows: readonly Record<string, unknown>[],
  overrides: Partial<{ importKey: string; projectId: ProjectId; orgId: OrgId }> = {},
): ImportIssuesInput {
  counter += 1;
  return importIssuesSchema.parse({
    orgId: overrides.orgId ?? t.org.id,
    projectId: overrides.projectId ?? t.project.id,
    importKey: overrides.importKey ?? `import-key-${counter}`,
    rows,
  });
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("imports");
});

beforeEach(() => {
  resetRateLimits();
  registerEventHandlers();
});

afterEach(() => {
  unregisterEventHandlers();
  resetEventBus();
});

afterAll(() => {
  cleanup();
});

describe("issueService.importIssues", () => {
  it("creates every row in file order, numbered after the highest number used", async () => {
    await issueRepo.insertIssue(
      issueInput(tenant.org.id, tenant.project.id, { title: "Existing" }),
      tenant.userIds.member,
      7,
    );

    const result = await issueService.importIssues(
      tenant.actors.member,
      batch(tenant, [
        { title: "First", description: "d1", status: "todo", priority: "high" },
        { title: "Second" },
        { title: "Third", dueAt: "2030-01-01T00:00:00.000Z" },
      ]),
    );

    expect(result.replayed).toBe(false);
    expect(result.issues.map((i) => i.title)).toEqual(["First", "Second", "Third"]);
    expect(result.issues.map((i) => i.number)).toEqual([8, 9, 10]);
    expect(result.issues[0]).toMatchObject({
      description: "d1",
      status: "todo",
      priority: "high",
      authorId: tenant.userIds.member,
      parentId: null,
      estimate: null,
    });
    expect(result.issues[2]?.dueAt).toBe("2030-01-01T00:00:00.000Z");

    expect(await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id)).toBe(11);
  });

  it("resolves assignees and labels", async () => {
    const other = await createTenant("imports-other");
    await labelRepo.insertLabel({
      orgId: other.org.id,
      name: "bug",
      color: "#ff0000",
      description: "theirs",
    });
    await labelRepo.insertLabel({
