    if (!removed) throw new Error("fixture");
    await memberRepo.archiveMember(tenant.org.id, removed.id);

    const result = await issueService.importIssues(
      tenant.actors.member,
      batch(tenant, [
        { title: "Row A", assigneeEmail: "ADMIN@imports.test", labels: ["Bug", "new", "new"] },
        { title: "Row B", assigneeEmail: "viewer@imports.test", labels: ["bug", "new"] },
        { title: "Row C", assigneeEmail: "owner@imports-other.test" },
        { title: "Row D", assigneeEmail: "nobody@nowhere.test" },
      ]),
    );

    expect(result.issues.map((i) => i.assigneeId)).toEqual([
      tenant.userIds.admin,
      null,
      null,
